  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Direct Object Pronouns$j$, $j${"readings": [{"title": "1 John 4 (King James Version)", "url": "/portal/bible/1John/4"}], "body": "First John 4:19 says, We love him, because he first loved us. The words him and us are direct objects, the people who receive the action. In Spanish, direct object pronouns replace nouns so that we do not repeat ourselves.\n\nThe pronouns are me, te, lo, la, nos, os, los, las. Lo replaces a masculine singular noun or him. La replaces a feminine singular noun or her. Los and las are the plurals.\n\nPlace the pronoun right before the conjugated verb. ¿Tienes la Biblia? Sí, la tengo. ¿Ves a Pedro? Sí, lo veo. In a negative sentence, no goes before the pronoun: No la tengo. With an infinitive or a present participle, the pronoun may go before the verb or attach to the end. Voy a leerlo or Lo voy a leer. Estoy escribiéndola or La estoy escribiendo.\n\nWorked example: ¿Leíste los salmos? Sí, los leí. ¿Quién invitó a las visitas? Mi pastor las invitó. Common mistake: using the pronoun after the verb, as in Tengo la, or choosing the wrong gender. The pronoun matches the noun it replaces, not the speaker.\n\nYour task: (1) Answer using a pronoun: ¿Tienes el libro? ¿Ves a tus amigas? ¿Comiste las frutas? (2) Rewrite two of your answers with an infinitive.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, 1 John 4:19 says, We love him, because he first loved us. Him and us are direct objects.\n\nNow watch this. Direct object pronouns replace nouns. Me, te, lo, la, nos, os, los, las.\n\nLo is him or masculine it. La is her or feminine it. The pronoun goes before the conjugated verb. ¿Tienes la Biblia? Sí, la tengo. ¿Ves a Pedro? Sí, lo veo.\n\nWith an infinitive, you may attach it. Voy a leerlo, or Lo voy a leer.\n\nThe pronoun matches the noun it replaces.\n\nYour task is to answer three questions using pronouns and then rewrite two with an infinitive. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Direct Object Pronouns$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Indirect Object Pronouns and Verbs Like Gustar$j$, $j${"readings": [{"title": "Psalm 40 (King James Version)", "url": "/portal/bible/Psalms/40"}], "body": "Psalm 40:8 says, I delight to do thy will, O my God. Delight, in Spanish, is expressed with a verb like gustar, where the thing that pleases is the subject. First we learn indirect object pronouns, which tell to whom or for whom an action is done.\n\nThe pronouns are me, te, le, nos, os, les. Le doy la Biblia a mi amigo means I give the Bible to my friend. Place them before the conjugated verb, just like direct objects. Common verbs are dar, decir, escribir, mandar, regalar, enseñar, prestar and pedir. Le escribo una carta a mi abuela. Les enseño español a los niños. The phrase a mi amigo can be dropped when the person is clear, but the pronoun le stays.\n\nWhen an indirect and a direct object pronoun appear together, the indirect comes first, and le or les becomes se before lo, la, los or las. Le doy el libro becomes Se lo doy.\n\nVerbs like gustar use the same pronouns: me gusta, te encanta, le interesa, nos importa, les falta, me duele. The verb agrees with the thing that pleases. Me gustan los salmos. Nos encanta cantar.\n\nWorked example: ¿Qué te gusta? Me gusta la música, y a mi hermana le gustan los libros. Common mistake: saying Yo gusto la música. The thing that pleases is the subject.\n\nYour task: (1) Write five sentences with indirect object pronouns. (2) Write five sentences about what pleases you and your family.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 40:8 says, I delight to do thy will, O my God. We express delight with a verb like gustar.\n\nNow watch this. Indirect object pronouns tell to whom or for whom. Me, te, le, nos, os, les. Le doy la Biblia a mi amigo.\n\nWhen two pronouns meet, the indirect comes first, and le becomes se before lo or la. Le doy el libro becomes Se lo doy.\n\nVerbs like gustar use these pronouns. Me gusta la música. Me gustan los salmos. Nos encanta cantar. Me duele la cabeza.\n\nDo not say Yo gusto la música. The thing that pleases is the subject.\n\nYour task is to write five sentences with indirect objects and five about what pleases you. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Indirect Object Pronouns and Verbs Like Gustar$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Comparisons and Superlatives$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Proverbs 16:16 says, How much better is it to get wisdom than gold! and to get understanding rather to be chosen than silver! This verse compares two things, and Spanish has clear patterns for that.\n\nTo say more or less, use más or menos plus the adjective plus que. Mi hermano es más alto que yo. Esta clase es menos difícil que la otra. To say equal, use tan plus the adjective plus como. Soy tan alto como tú. For nouns, use tanto, tanta, tantos or tantas plus the noun plus como. Tengo tantos libros como tú. Tengo tantas amigas como ellos. Before a number, use de instead of que: Tengo más de veinte libros.\n\nSome adjectives have irregular comparisons: bueno becomes mejor, malo becomes peor, joven becomes menor, viejo becomes mayor. Mi hermano mayor es mejor cantante que yo.\n\nFor the superlative, the most or the least, use el, la, los or las plus más or menos plus the adjective plus de. Es la chica más amable de la clase. Es el mejor libro de la biblioteca. The ending ísimo means very: altísimo, buenísimo.\n\nWorked example: Mi iglesia es más grande que mi escuela, pero mi escuela es tan bonita como mi iglesia. Common mistake: Más mejor. Mejor already means better, so do not add más.\n\nYour task: (1) Compare yourself with a family member in four sentences. (2) Write three superlative sentences about your school, church and city.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Proverbs 16:16 says, How much better is it to get wisdom than gold! This verse compares two things.\n\nNow watch this. More or less: más or menos plus the adjective plus que. Mi hermano es más alto que yo.\n\nEqual: tan plus the adjective plus como. Soy tan alto como tú. For nouns, tanto, tanta, tantos, tantas. Tengo tantos libros como tú.\n\nBefore a number, use de. Tengo más de veinte libros.\n\nIrregular: mejor, peor, mayor, menor. Do not say más mejor.\n\nSuperlative: el, la, los, las plus más plus the adjective plus de. Es la chica más amable de la clase.\n\nYour task is to compare yourself with a relative and write three superlative sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Comparisons and Superlatives$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Por and Para$j$, $j${"readings": [{"title": "Jeremiah 29 (King James Version)", "url": "/portal/bible/Jeremiah/29"}], "body": "Jeremiah 29:11 says, For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end. English uses for for many ideas. Spanish divides them between por and para.\n\nUse para for purpose, goal or destination. Estudio para aprender means I study in order to learn. Este regalo es para ti means this gift is for you. Salgo para Miami means I leave for Miami. La tarea es para el lunes means the homework is due Monday. Trabajo para una iglesia means I work for a church. Para mí means in my opinion.\n\nUse por for cause, movement through a place, a length of time, an exchange and on behalf of. Gracias por la ayuda means thanks for the help. Caminé por el parque means I walked through the park. Estudié por dos horas means I studied for two hours. Pagué diez dólares por el libro means I paid ten dollars for the book. Oro por mi familia means I pray for my family. Por la mañana means in the morning.\n\nA helpful tip: para looks forward to a goal, and por looks back at a reason.\n\nWorked example: Voy a la iglesia para orar, y doy gracias por la comida. Common mistake: using para for duration. Say Viví allí por dos años.\n\nYour task: (1) Write six sentences, three with por and three with para. (2) Explain which meaning of each preposition you used.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Jeremiah 29:11 says, I know the thoughts that I think toward you, saith the LORD, thoughts of peace. English uses for for many ideas. Spanish divides them between por and para.\n\nNow watch this. Para is purpose, goal or destination, deadlines and recipients. Estudio para aprender. Este regalo es para ti. Salgo para Miami.\n\nPor is cause, movement through, time, exchange and on behalf of. Gracias por la ayuda. Caminé por el parque. Estudié por dos horas. Oro por mi familia.\n\nHere is a tip. Para looks forward to a goal. Por looks back at a reason.\n\nYour task is to write six sentences with por and para and explain each choice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Por and Para$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Pronouns, Comparisons, Por and Para$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. First John 4:19 says, We love him, because he first loved us.\n\nPart 1: Explain direct object pronouns, list them, and rewrite five Spanish sentences using them, including one with an infinitive.\nPart 2: Explain indirect object pronouns, rewrite two sentences using se lo or se la, and write five sentences with verbs like gustar.\nPart 3: Write six comparisons in Spanish: two of inequality, two of equality and two superlatives.\nPart 4: Explain at least three uses of por and three uses of para with an example sentence for each.\nPart 5: Write a Spanish paragraph of at least eight sentences about a gift you gave or received, using object pronouns, one comparison and por and para.\nPart 6: Explain how Proverbs 16:16 and Philippians 2:3 guide you when you compare yourself with others.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Part 6: 5 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Pronouns, Comparisons, Por and Para$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Who Receives the Gift$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a gift or act of kindness you gave or received, (2) shares at least three Spanish sentences about it using object pronouns, por or para, and (3) connects your answer to 1 John 4:19 or Psalm 40:8. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it healthy to compare our work to a standard instead of to other people?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Who Receives the Gift$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Direct Object Pronouns$j$, $j${"questions": [{"q": "The pronoun that replaces la Biblia is:", "options": ["Le", "La", "Las", "Lo"]}, {"q": "Sí, lo veo means:", "options": ["Yes, he sees me", "Yes, I see her", "Yes, I saw them", "Yes, I see him"]}, {"q": "Where does the pronoun go in No la tengo?", "options": ["After the verb", "At the end of the sentence", "Before the verb", "Before no"]}, {"q": "Voy a leerlo can also be:", "options": ["Voy a lo leer", "Lo voy a leer", "Voy lo a leer", "Lo a voy leer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Direct Object Pronouns$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,1}'::int[], array[$j$La replaces a feminine singular noun.$j$,$j$Lo is the masculine singular direct object.$j$,$j$The pronoun goes before the conjugated verb.$j$,$j$The pronoun may go before or attach to the infinitive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Direct Object Pronouns$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Indirect Object Pronouns and Verbs Like Gustar$j$, $j${"questions": [{"q": "Le escribo una carta a mi abuela means:", "options": ["I wrote my grandmother", "I write a letter to my grandmother", "I write her a grandmother", "She writes me a letter"]}, {"q": "Se lo doy replaces:", "options": ["Le doy el libro", "Les doy la mesa", "Me doy el libro", "Lo doy el libro"]}, {"q": "Me gustan los salmos uses gustan because:", "options": ["Gustar is irregular", "Me is plural", "Salmos is plural", "Yo is plural"]}, {"q": "Nos encanta cantar means:", "options": ["We love to sing", "We sang", "We hear singing", "They love us"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Indirect Object Pronouns and Verbs Like Gustar$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,0}'::int[], array[$j$Le is the indirect object, to her.$j$,$j$Le becomes se before lo.$j$,$j$The verb agrees with the thing that pleases.$j$,$j$Encantar works like gustar.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Indirect Object Pronouns and Verbs Like Gustar$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Comparisons and Superlatives$j$, $j${"questions": [{"q": "Mejor means:", "options": ["Worse", "Better", "Younger", "Older"]}, {"q": "Soy tan alto como tú means:", "options": ["I am taller than you", "You are taller", "I am as tall as you", "I am the tallest"]}, {"q": "Before a number, use:", "options": ["De", "Que", "Más", "Como"]}, {"q": "El mejor libro de la biblioteca is a:", "options": ["Command", "Superlative", "Comparison of equality", "Question"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Comparisons and Superlatives$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,1}'::int[], array[$j$Mejor is the comparative of bueno.$j$,$j$Tan plus an adjective plus como shows equality.$j$,$j$Más de veinte means more than twenty.$j$,$j$El plus mejor plus de forms the superlative.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Comparisons and Superlatives$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Por and Para$j$, $j${"questions": [{"q": "Estudio para aprender means:", "options": ["I study in order to learn", "I study because of learning", "I learn by studying", "I studied for learning"]}, {"q": "Gracias por la ayuda uses por because it shows:", "options": ["A deadline", "A destination", "A reason", "A recipient"]}, {"q": "Este regalo es ___ ti.", "options": ["por", "para", "con", "de"]}, {"q": "Estudié ___ dos horas.", "options": ["por", "a", "para", "en"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Por and Para$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,0}'::int[], array[$j$Para plus an infinitive shows purpose.$j$,$j$Por introduces the reason for thanks.$j$,$j$Para shows the recipient.$j$,$j$Por shows a length of time.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Por and Para$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Pronouns, Comparisons, Por and Para$j$, $j${"questions": [{"q": "The pronoun that replaces los libros is:", "options": ["Les", "Las", "Los", "Lo"]}, {"q": "Le doy el regalo becomes:", "options": ["Se lo doy", "Me lo doy", "Lo le doy", "Le lo doy"]}, {"q": "Me gustan las flores uses gustan because flores is:", "options": ["Feminine singular", "A verb", "A person", "Plural"]}, {"q": "Mi hermana es mayor que yo means:", "options": ["My sister is younger than I am", "My sister is taller", "My sister is as old as I am", "My sister is older than I am"]}, {"q": "Tengo tantos amigos como tú means:", "options": ["I have fewer friends than you", "I have many friends", "I have as many friends as you", "I have more friends than you"]}, {"q": "Salgo ___ Orlando mañana.", "options": ["por", "ante", "para", "de"]}, {"q": "Camino ___ el parque.", "options": ["con", "para", "por", "a"]}, {"q": "Más de treinta personas uses de because it comes before:", "options": ["A verb", "A pronoun", "A number", "A noun"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Pronouns, Comparisons, Por and Para$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3,2,2,2,2}'::int[], array[$j$Los replaces a masculine plural noun.$j$,$j$Le becomes se before lo.$j$,$j$The verb agrees with the thing that pleases.$j$,$j$Mayor means older.$j$,$j$Tantos plus a noun plus como compares equal amounts.$j$,$j$Para shows destination.$j$,$j$Por shows movement through a place.$j$,$j$Use de instead of que before a number.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Pronouns, Comparisons, Por and Para$j$ on conflict (item_id) do nothing;
